namespace leveldb {

bool GetVarint32(Slice* input, uint32_t* value) {
    const char* data = input->data();
    const char* limit = data + input->size();
    uint32_t result = 0;
    int shift = 0;
    for (int i = 0; i < 5; ++i) {
        if (data >= limit) {
            return false;
        }
        uint8_t byte = static_cast<uint8_t>(*data);
        ++data;
        result |= static_cast<uint32_t>(byte & 0x7F) << shift;
        if ((byte & 0x80) == 0) {
            *value = result;
            input->remove_prefix(data - input->data());
            return true;
        }
        shift += 7;
    }
    return false;
}

